<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {useAuthApi,isStaleAuthError,dateTime,taskLabel} from '../api';
const api=useAuthApi();
const props=defineProps<{refreshKey:number}>();const emit=defineEmits(['changed']);const items=ref<any[]>([]);const filter=ref('pending');const editing=ref<any>(null);const when=ref('');const busy=ref(false);
const filtered=computed(()=>filter.value==='all'?items.value:items.value.filter(t=>filter.value==='overdue'?t.overdue:t.status===filter.value));
let refreshRequest=0;
async function refresh(){const request=++refreshRequest;try{const result=await api('/clinician/tasks');if(request===refreshRequest)items.value=result.items;}catch(e){if(request===refreshRequest&&!isStaleAuthError(e))ElMessage.error((e as Error).message);}}
async function cancel(row:any){try{await ElMessageBox.confirm('取消后，患者将无法开始这次任务。','取消随访安排',{confirmButtonText:'确认取消',cancelButtonText:'保留安排',type:'warning'});await api('/clinician/tasks/'+row.id,'PATCH',{cancelled:true});await refresh();emit('changed');}catch(e){if(e instanceof Error&&!isStaleAuthError(e))ElMessage.error(e.message);}}
function edit(row:any){editing.value=row;when.value=new Date(new Date(row.scheduled_at).getTime()+8*3600000).toISOString().slice(0,16);}
async function save(){busy.value=true;try{await api('/clinician/tasks/'+editing.value.id,'PATCH',{scheduledAt:new Date(when.value+':00+08:00').toISOString()});editing.value=null;await refresh();emit('changed');}catch(e){if(!isStaleAuthError(e))ElMessage.error((e as Error).message);}finally{busy.value=false;}}
onMounted(refresh);watch(()=>props.refreshKey,refresh);
</script>
<template><section class="page-heading"><div><span class="eyebrow">SCHEDULE</span><h1>随访计划</h1><p>集中查看安排与完成状态，及时跟进逾期任务。</p></div></section><section class="panel"><div class="panel-toolbar"><el-radio-group v-model="filter"><el-radio-button value="pending">待随访</el-radio-button><el-radio-button value="overdue">已逾期</el-radio-button><el-radio-button value="submitted">待审核</el-radio-button><el-radio-button value="all">全部</el-radio-button></el-radio-group><small class="muted">北京时间</small></div><el-table :data="filtered" empty-text="当前筛选下没有随访安排"><el-table-column label="患者" prop="name" min-width="120"/><el-table-column label="任务" prop="title" min-width="160"/><el-table-column label="随访时间" min-width="155"><template #default="{row}">{{dateTime(row.scheduled_at)}}</template></el-table-column><el-table-column label="状态" width="120"><template #default="{row}"><span class="status" :class="row.overdue?'orange':row.status==='reviewed'?'green':'gray'">{{row.overdue?'已逾期':taskLabel(row.status)}}</span></template></el-table-column><el-table-column label="操作" width="160"><template #default="{row}"><template v-if="row.status==='pending'"><el-button text type="primary" @click="edit(row)">改期</el-button><el-button text @click="cancel(row)">取消安排</el-button></template><span v-else class="muted">{{taskLabel(row.status)}}</span></template></el-table-column></el-table></section><el-dialog :model-value="!!editing" @update:model-value="!$event&&(editing=null)" title="修改随访时间" width="450px"><el-form label-position="top"><el-form-item label="新的随访时间" for="reschedule-time"><input id="reschedule-time" v-model="when" type="datetime-local" class="native-input"/></el-form-item></el-form><template #footer><el-button @click="editing=null">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存改期</el-button></template></el-dialog></template>
